		t.Errorf("window output mismatch:\n got: %q\nwant only the earlier result %q", got, slidingLateWantFirstWindow)
	}
	if out.calls != 1 {
		t.Errorf("window writer was called %d times, want exactly 1 (nothing after the failure)", out.calls)
	}
