		`{"type":"event","key":"k","time":900,"value":7}`, // line 1
		`{"type":"watermark","time":1000}`,                // line 2 closes [0,1000)
		`{"type":"event","key":"k","time":999,"value":1}`, // line 3 complete and late
		``,
	}, "\n")
