	// signed 64-bit values with no precision loss or sign flip.
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "k", Start: M - 11, End: M - 4, Count: 1, Sum: 2},
		{Key: "k", Start: M - 7, End: M, Count: 2, Sum: 5},
	}
