		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
	got := decodeAggregateResults(t, stdout)
	if len(got) != 1 || got[0] != (AggregateResult{Key: "k", Start: 0, End: M, Count: 2, Sum: 12}) {
		t.Fatalf("decoded rows = %v", got)
	}
