276		}
277		if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
278			t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
279		}
280		if !strings.Contains(inputErr.Reason, `for key "k"`) {
281			t.Fatalf("reason = %q, want it to name the key", inputErr.Reason)
282		}
