290			t.Errorf("reason must not blame the safe window [300,1300): %q", inputErr.Reason)
291		}
292		if stdout != "" || stderr != "" {
293			t.Fatalf("nothing may be emitted or logged after the immediate failure, got stdout=%q stderr=%q", stdout, stderr)
294		}
295	}
296	
297	// Overflow is judged at the addition that crosses the boundary, not from the
298	// eventual mathematical total: a later opposite-sign event from the other
299	// partition would bring every window sum back into range, but it can never
300	// erase the overflow that already happened. Neither that event nor any
301	// following watermark is processed, so no open window is published.
302	func TestAggregatePartitionedSlidingSumOverflowNotMaskedByLaterEvents(t *testing.T) {
303		input := strings.Join([]string{
304			fmt.Sprintf(`{"type":"event","key":"k","time":700,"value":%d,"partition":0}`, math.MaxInt64),
305			`{"type":"event","key":"k","time":800,"value":1,"partition":1}`,  // line 2: merged MaxInt64 + 1
306			`{"type":"event","key":"k","time":900,"value":-1,"partition":0}`, // would cancel it: never processed
307			`{"type":"watermark","time":1600,"partition":0}`,
308			`{"type":"watermark","time":1600,"partition":1}`,
309		}, "\n")
310		stdout, stderr, err := runPartitionedSliding(t, input, 1000, 600, 2)
311		if err == nil {
312			t.Fatal("expected cumulative sum overflow, got nil")
313		}
314		inputErr, ok := err.(*InputError)
315		if !ok {
316			t.Fatalf("expected *InputError, got %T: %v", err, err)
317		}
318		if inputErr.Line != 2 {
319			t.Errorf("line = %d, want 2", inputErr.Line)
320		}
321		if !strings.Contains(inputErr.Reason, "cumulative sum overflow") {
322			t.Fatalf("reason = %q, want cumulative sum overflow", inputErr.Reason)
323		}
324		// t=800 is in [0,1000) and [600,1600), updated in ascending start order,
325		// so the first crossing -- and the named window -- is [0,1000).
326		if !strings.Contains(inputErr.Reason, "window [0,1000)") {
327			t.Fatalf("reason = %q, want it to name the first overflowing window [0,1000)", inputErr.Reason)
328		}
329		if !strings.Contains(inputErr.Reason, "9223372036854775807 + 1") {
330			t.Fatalf("reason = %q, want it to show accumulated value and new value", inputErr.Reason)
331		}
332		if stdout != "" {
333			t.Fatalf("no window had closed before the failure; nothing may be emitted, got %q", stdout)
334		}
335		if stderr != "" {
336			t.Fatalf("late log must stay empty for non-late events, got %q", stderr)
337		}
338	}
