	return []string{
		``, // line 1 blank
		`{"type":"event","key":"k","time":900,"value":7,"partition":0}`, // line 2
		`{"type":"watermark","time":5000,"partition":0}`,                // line 3
		`{"type":"watermark","time":1000,"partition":1}`,                // line 4: effective = 1000
		``, // line 5 blank
	}
